const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['a', 'b', 'c', '', '-x', '+y', ' z'];

for (let t = 0; t < 30000; t++) {
  const k = 1 + rnd(alpha.length);
  const a = Array.from({ length: rnd(14) }, () => alpha[rnd(k)]);
  const b = Array.from({ length: rnd(14) }, () => alpha[rnd(k)]);
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  const edits = s.filter((e) => e.op !== 'equal').length;
  assert.equal(edits, a.length + b.length - 2 * lcs(a, b), JSON.stringify({ a, b, s }));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  assert.deepEqual(diffLines(a, b), s);
  for (const context of [0, 1, 2, 3, 10]) {
    const hunks = unifiedHunks(a, b, { context });
    if (edits === 0) assert.deepEqual(hunks, []);
    assert.deepEqual(applyHunks(a, hunks), b);
    for (const h of hunks) {
      // Coordinates: verify old/new ranges against full inputs.
      const oldSeg = h.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1));
      const newSeg = h.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1));
      const os = h.oldLines === 0 ? h.oldStart : h.oldStart - 1;
      const ns = h.newLines === 0 ? h.newStart : h.newStart - 1;
      assert.deepEqual(a.slice(os, os + h.oldLines), oldSeg);
      assert.deepEqual(b.slice(ns, ns + h.newLines), newSeg);
